{"explanation":"A Galton board turns repeated left-or-right choices into a distribution: after six rows, a ball’s final bin records how many times it went right. Since each path has probability \(2^{-6}\), the bin probabilities follow the binomial coefficients \(1,6,15,20,15,6,1\), producing the familiar bell-shaped pattern.","manimCode":"const title = new Text({ text: 'A Galton board builds a binomial distribution', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.45, 0]);
scene.add(title);

const rows = 6;
const dx = 0.72;
const dy = 0.57;
const topY = 2.65;
const boardLeft = -3.0;
const boardRight = 3.0;
const sideLeft = new Line({ start: [boardLeft, topY + 0.35, 0], end: [boardLeft, -1.45, 0], color: GRAY });
const sideRight = new Line({ start: [boardRight, topY + 0.35, 0], end: [boardRight, -1.45, 0], color: GRAY });
scene.add(sideLeft, sideRight);

const pegs = [];
for (let r = 0; r < rows; r++) {
  const y = topY - r * dy;
  for (let i = 0; i <= r; i++) {
    const x = (i - r / 2) * dx;
    const peg = new Dot({ point: [x, y, 0], color: BLUE_C });
    peg.scale(0.42);
    pegs.push(peg);
  }
}
scene.add(...pegs);

const binLines = [];
for (let i = 0; i <= rows + 1; i++) {
  const x = (i - (rows + 1) / 2) * dx;
  const line = new Line({ start: [x, -1.45, 0], end: [x, -2.35, 0], color: GRAY });
  binLines.push(line);
}
scene.add(...binLines);

const counts = Array(rows + 1).fill(0);
const bars = [];
for (let j = 0; j <= rows; j++) {
  const x = (j - rows / 2) * dx;
  const bar = new Rectangle({ width: 0.55, height: 0.08, color: TEAL });
  bar.setFill(TEAL, 0.85);
  bar.moveTo([x, -3.0, 0]);
  bars.push(bar);
}
scene.add(...bars);

const note = new Text({ text: 'Each row: left or right  •  final bin = number of rights', color: YELLOW, fontSize: 19 });
note.moveTo([0, -3.55, 0]);
scene.add(note);

// Send balls down random left/right paths and stack them in their landing bins.
const balls = 18;
for (let b = 0; b < balls; b++) {
  const choices = [];
  let rights = 0;
  for (let r = 0; r < rows; r++) {
    const goRight = Math.random() < 0.5;
    choices.push(goRight);
    if (goRight) rights++;
  }
  const ball = new Dot({ point: [0, topY + 0.62, 0], color: GOLD });
  ball.scale(0.62);
  scene.add(ball);
  let posX = 0;
  for (let r = 0; r < rows; r++) {
    posX += choices[r] ? dx / 2 : -dx / 2;
    const targetY = topY - r * dy - 0.17;
    await scene.play(new Shift(ball, { direction: [posX - ball.getCenter()[0], targetY - ball.getCenter()[1], 0] }));
  }
  counts[rights]++;
  const landingX = (rights - rows / 2) * dx;
  const stackY = -2.43 - (counts[rights] - 1) * 0.13;
  await scene.play(new Shift(ball, { direction: [landingX - ball.getCenter()[0], stackY - ball.getCenter()[1], 0] }));
  const newHeight = 0.08 + counts[rights] * 0.13;
  const newBar = new Rectangle({ width: 0.55, height: newHeight, color: TEAL });
  newBar.setFill(TEAL, 0.85);
  newBar.moveTo([landingX, -3.0 + newHeight / 2, 0]);
  scene.remove(bars[rights]);
  bars[rights] = newBar;
  scene.add(newBar);
}

const formula = new Text({ text: 'Bin probabilities:  1 : 6 : 15 : 20 : 15 : 6 : 1   (out of 64)', color: WHITE, fontSize: 21 });
formula.moveTo([0, 3.02, 0]);
scene.add(formula);
for (const bar of bars) makeHoverable(bar, scene, { hoverScale: 1.08, hoverColor: YELLOW });
await scene.wait(999999);"}

